    axis: str
    group_index: int
    differing_index: int
    baseline_index: int
    max_abs_diff: float

    def to_text(self) -> str:
        return (
            f"Replicated along {self.axis}: group {self.group_index}, "
            f"index {self.differing_index} differs from {self.baseline_index} "
            f"(max_abs_diff={self.max_abs_diff:.6e})"
        )


class GeneralWarning(_StrictBase):
    kind: Literal["general"] = "general"
    category: str
    message: str

    def to_text(self) -> str:
        return self.message


AnyWarning = Annotated[
    Union[ReplicatedMismatchWarning, GeneralWarning],
    Discriminator("kind"),
]


class WarningSink:
    def __init__(self) -> None:
        self._stack: list[list[AnyWarning]] = []
        self._output_format: str = "text"

    def set_output_format(self, output_format: str) -> None:
        self._output_format = output_format

    @contextmanager
    def context(self) -> Generator[list[AnyWarning], None, None]:
        bucket: list[AnyWarning] = []
        self._stack.append(bucket)
        try:
