from pathlib import Path
from typing import Any, Optional

import polars as pl

from sglang.srt.debug_utils.dump_loader import ValueWithMeta


def _render_polars_as_text(df: pl.DataFrame, *, title: Optional[str] = None) -> str:
    """Render a Polars DataFrame as a plain-text table.

    The result always contains ``title`` (when given) and every column name of
    ``df``, followed by one line per row. Empty DataFrames (no rows and/or no
    columns) are handled without error.
    """
    lines: list[str] = []
    if title is not None:
        lines.append(title)

    columns: list[str] = list(df.columns)
    if columns:
        rendered_rows: list[list[str]] = [
            ["" if value is None else str(value) for value in row]
            for row in df.iter_rows()
        ]

        widths: list[int] = [len(str(col)) for col in columns]
        for rendered in rendered_rows:
            for i, cell in enumerate(rendered):
                widths[i] = max(widths[i], len(cell))

        lines.append(
            " | ".join(str(col).ljust(widths[i]) for i, col in enumerate(columns))
        )
        lines.append("-+-".join("-" * widths[i] for i in range(len(columns))))
        for rendered in rendered_rows:
            lines.append(
                " | ".join(rendered[i].ljust(widths[i]) for i in range(len(columns)))
            )

    return "\n".join(lines)


def _extract_parallel_info(row_data: dict[str, Any], info: dict[str, Any]) -> None:
    """Write ``{rank}/{size}`` entries from a parallel-info dict into ``row_data``.

    For each ``<base>_rank`` key with a matching ``<base>_size`` key, sets
    ``row_data[<base>] = "{rank}/{size}"``. No-op if ``info`` is empty or contains
    an ``"error"`` key. ``_rank`` keys without a matching ``_size`` are skipped.
    """
    if not info or "error" in info:
        return

    suffix = "_rank"
    for key in info:
        if not key.endswith(suffix):
            continue
        base = key[: -len(suffix)]
        size_key = f"{base}_size"
        if size_key in info:
            row_data[base] = f"{info[key]}/{info[size_key]}"


def _collect_rank_info(
    df: pl.DataFrame, dump_dir: Path
) -> Optional[list[dict[str, Any]]]:
    """Collect per-rank parallel-topology info from the ``input_ids`` dumps."""
    if "name" not in df.columns:
        return None

    rows = df.filter(pl.col("name") == "input_ids").to_dicts()
    if not rows:
        return None

    dump_dir = Path(dump_dir)
    result: list[dict[str, Any]] = []
    seen_ranks: set[Any] = set()
    for row in rows:
        rank = row.get("rank")
        if rank in seen_ranks:
            continue
        seen_ranks.add(rank)

        row_data: dict[str, Any] = {"rank": rank}
        loaded = ValueWithMeta.load(dump_dir / row["filename"])
        info = loaded.meta.get("sglang_parallel_info") or {}
        if isinstance(info, dict):
            _extract_parallel_info(row_data, info)
        result.append(row_data)

    return result


def _collect_input_ids_and_positions(
